#!/usr/bin/env node
// Auto-generated by Graft Compiler
// Edge: LogicReviewer -> SeniorReviewer

const fs = require('fs');
const path = require('path');

const INPUT = path.resolve('.graft/session/node_outputs/logicreviewer.json');
const OUTPUT = path.resolve('.graft/session/node_outputs/logicreviewer_to_seniorreviewer.json');
const TOKEN_LOG = path.resolve('.graft/token_log.txt');

if (!fs.existsSync(INPUT)) {
  // Graceful no-op: this hook fires on ALL Write calls,
  // so the source output may not exist yet (different agent writing).
  process.exit(0);
}

const raw = fs.readFileSync(INPUT, 'utf-8');
const data = JSON.parse(raw);

function isEmpty(v) {
  if (v === null || v === undefined || v === '') return true;
  if (Array.isArray(v) && v.length === 0) return true;
  if (typeof v === 'object' && !Array.isArray(v) && Object.keys(v).length === 0) return true;
  return false;
}
function compact(data) {
  if (data === null || data === undefined) return undefined;
  if (typeof data !== 'object') return data;
  if (Array.isArray(data)) {
    return data.map(item => compact(item)).filter(item => !isEmpty(item));
  }
  const result = {};
  for (const [key, val] of Object.entries(data)) {
    const c = compact(val);
    if (!isEmpty(c)) result[key] = c;
  }
  return result;
}

let result = {
  "bugs": data["bugs"],
  "edge_cases": data["edge_cases"]
};
result = compact(result);

const output = JSON.stringify(result);
fs.writeFileSync(OUTPUT, output);

// Token accounting
const original = Buffer.byteLength(raw);
const transformed = Buffer.byteLength(output);
const reduction = original > 0 ? Math.round((original - transformed) * 100 / original) : 0;
const timestamp = new Date().toISOString().replace('T', ' ').slice(0, 19);

fs.appendFileSync(TOKEN_LOG, `[${timestamp}] Edge LogicReviewer->SeniorReviewer | ${original}B -> ${transformed}B (${reduction}% reduction)\n`);
